<?php require_once __DIR__ . '/ResourceController.php'; final class AdminController { public static function index(string $method, ?string $id = null): never { if ($method === 'GET' && $id === null) ResourceController::list('admins', ['Super Admin']); if ($method === 'GET') ResourceController::show('admins', $id, ['Super Admin']); if ($method === 'POST' && $id === null) ResourceController::collection('admins', ['Super Admin'], 201); if ($method === 'PUT' && $id !== null) ResourceController::update('admins', $id, ['Super Admin']); if ($method === 'DELETE' && $id !== null) ResourceController::delete('admins', $id); Response::error('Method not allowed', 'METHOD_NOT_ALLOWED', 405); } }
